+
+                logger.debug("--> deleting restored index [{}]", restoredIndex);
+                deleteIndex(restoredIndex);
+
+                success = true;
+            } finally {
+                if (success == false) {
+                    try {
+                        client().performRequest(new Request("DELETE", "/" + restoredIndex));
+                    } catch (ResponseException e) {
