+            logger.debug("--> applying verified read-only setting on [{}]", index);
+            updateIndexSettings(index, Settings.builder().put(VERIFIED_READ_ONLY_SETTING.getKey(), true));
+
+            logger.debug("--> creating snapshot [{}]", snapshot);
